// t==1 fused: p2 + p3f (state write + emitted out1), c packed
static void pass23f_6(double*restrict are, double*restrict aim,
                        const double*restrict cpk, double*restrict eo1) {
  for (int x = 0; x < 6; x++) {
    double* ar = are + (long)x * 72; double* ai = aim + (long)x * 72;
    for (int bb = 0; bb < 8; bb += 8)
      p2_6(ar + bb, ai + bb, Sr_6 + (long)bb * 8, Si_6 + (long)bb * 8);
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      p3f_6(Sr_6 + bb, Si_6 + bb, ar + bb, ai + bb, cpk + ((long)x*1 + k)*128, eo1, x, bb);
    }
  }
}
// final step: p2 into scratch, then emit directly (no state write). parity: 1 = transposed layout (odd t), 0 = natural
static void pass23e_6(double*restrict are, double*restrict aim,
                        const double*restrict csrc, double*restrict eo1, double*restrict eo2, int parity) {
  for (int x = 0; x < 6; x++) {
    double* ar = are + (long)x * 72; double* ai = aim + (long)x * 72;
    for (int bb = 0; bb < 8; bb += 8)
      p2_6(ar + bb, ai + bb, Sr_6 + (long)bb * 8, Si_6 + (long)bb * 8);
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      if (parity) {
        int nrow = 6 - bb; if (nrow > 8) nrow = 8;
        p3eT_6(Sr_6 + bb, Si_6 + bb, csrc + 2*((long)x*6*6 + (long)bb*6), nrow, eo1, eo2, x, bb);
      } else {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 6) { m0 = 0xff; m1 = 0x0f; }
        p3eN_6(Sr_6 + bb, Si_6 + bb, csrc + 2*((long)x*6*6 + bb), m0, m1, eo1, x, bb);
      }
    }
  }
}


static void rung_6(const double* const* srcx, const double* const* srcc,
                     double* const* dst1, double* const* dstm, int nreal, long m) {
  packB(srcx, Gr_6, Gi_6, 216);
  packBC(srcc, cG_6, 216);
  for (long t = 1; t <= m; t++) {
    for (long i2 = 0; i2 < 6*6; i2++) pb1_6(Gr_6 + 8*i2, Gi_6 + 8*i2);
    for (long x = 0; x < 6; x++)
      for (long z = 0; z < 6; z++) {
        long e = x*6*6 + z;
        pb2_6(Gr_6 + 8*e, Gi_6 + 8*e);
      }
    for (long x = 0; x < 6; x++)
      for (long y = 0; y < 6; y++) {
        long e = x*6*6 + y*6;
        pb3_6(Gr_6 + 8*e, Gi_6 + 8*e, cG_6 + 16*e);
      }
    if (t == 1) unpackB(Gr_6, Gi_6, dst1, nreal, 216);
  }
  unpackB(Gr_6, Gi_6, dstm, nreal, 216);
}


static void run_6(long B, long m, const double* x0, const double* c, double* out1, double* outm) {
  long b0 = 0;
  while (B - b0 >= 5) {
    int nreal = (B - b0 >= 8) ? 8 : (int)(B - b0);
    const double* sx[8]; const double* sc[8]; double* d1[8]; double* dm[8];
    for (int l = 0; l < 8; l++) {
      long bb = b0 + (l < nreal ? l : nreal - 1);
      sx[l] = x0 + 2*(long)bb*216;
      sc[l] = c + 2*(long)bb*216;
      d1[l] = out1 + 2*(long)bb*216;
      dm[l] = outm + 2*(long)bb*216;
    }
    rung_6(sx, sc, d1, dm, nreal, m);
    b0 += nreal;
  }
  for (long b = b0; b < B; b++) {
    const double* xb = x0 + 2 * (long)b * 216;
    const double* cb = c + 2 * (long)b * 216;
    double* o1 = out1 + 2 * (long)b * 216;
    double* om = outm + 2 * (long)b * 216;
    int useT = (m >= 3);
    int useN = (m >= 4);
    if (useT && useN) cprepBoth(cb, cPo_6, cPe_6, 6, 1, 8);
    else if (useT) cprepTpk(cb, cPo_6, 6, 1, 8);
    deintl(xb, Ar_6, Ai_6, 6, 8, 72);
    for (long t = 1; t <= m; t++) {
      pass1_6(Ar_6, Ai_6);
      if (t == m) {
        if (t & 1) pass23e_6(Ar_6, Ai_6, cb, (m == 1 ? o1 : om), (m == 1 ? om : 0), 1);
        else       pass23e_6(Ar_6, Ai_6, cb, om, 0, 0);
        break;
      }
      if (t == 1) {
        if (useT) { pass23f_6(Ar_6, Ai_6, cPo_6, o1); continue; }
        pass23_6(Ar_6, Ai_6, 0, cb, 2);
        emitT(Ar_6, Ai_6, o1, 0, 6, 8, 72, 0);
      } else if (t & 1) {
        pass23_6(Ar_6, Ai_6, cPo_6, 0, 0);
      } else {
        if (useN) pass23_6(Ar_6, Ai_6, cPe_6, 0, 0);
        else      pass23_6(Ar_6, Ai_6, 0, cb, 1);
      }
    }
  }
  _mm_sfence();
}

