static void pass1_8(double*restrict re, double*restrict im) {
#if P1ORD
  for (int bb = 0; bb < 8; bb += 8)
    for (int a = 0; a < 8; a++)
      p1_8(re + a * 8 + bb, im + a * 8 + bb);
#else
  for (int a = 0; a < 8; a++) {
    double* r = re + a * 8;
    double* i2 = im + a * 8;
    for (int bb = 0; bb < 8; bb += 8) p1_8(r + bb, i2 + bb);
  }
#endif
}
// kind: 0 -> p3 with split c planes; 1 -> p3d natural interleaved c; 2 -> p3c transposed interleaved c
static void pass23_8(double*restrict are, double*restrict aim,
                       const double*restrict cpk,
                       const double*restrict csrc, int kind) {
  double* s0r = Sr_8; double* s0i = Si_8;
  double* s1r = Sr2_8; double* s1i = Si2_8;
  for (int x = 0; x < 8; x++) {
    double* ar = are + (long)x * 72; double* ai = aim + (long)x * 72;
    double* pr = are + (long)(x-1) * 72; double* pi = aim + (long)(x-1) * 72;
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      p2_8(ar + bb, ai + bb, s0r + (long)bb * 8, s0i + (long)bb * 8);
    }
#if PIPE==0
    if (1) {
      double* t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
      double* pr = ar; double* pi = ai;
      int x_ = x + 1;
      (void)x_;
      for (int k = 0; k < 1; k++) {
        int bb = 8 * k;
        if (kind == 0)
          p3_8(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)x*1 + k)*128);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 8) { m0 = 0xff; m1 = 0xff; }
          p3d_8(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*8*8 + bb), m0, m1);
        } else {
          int nrow = 8 - bb; if (nrow > 8) nrow = 8;
          p3c_8(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*8*8 + (long)bb*8), nrow);
        }
      }
      // swap back so outer swap restores
      t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
    }
#else
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      if (x > 0) {
        if (kind == 0)
          p3_8(s1r + bb, s1i + bb, pr + bb, pi + bb, cre + (long)(x-1)*72 + bb, cim + (long)(x-1)*72 + bb);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 8) { m0 = 0xff; m1 = 0xff; }
          p3d_8(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*8*8 + bb), m0, m1);
        } else {
          int nrow = 8 - bb; if (nrow > 8) nrow = 8;
          p3c_8(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*8*8 + (long)bb*8), nrow);
        }
      }
    }
#endif
    double* t;
    t = s0r; s0r = s1r; s1r = t;
    t = s0i; s0i = s1i; s1i = t;
  }
#if PIPE==1
  {
    double* pr = are + (long)(8-1) * 72; double* pi = aim + (long)(8-1) * 72;
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      if (kind == 0)
        p3_8(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)(8-1)*1 + k)*128);
      else if (kind == 1) {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 8) { m0 = 0xff; m1 = 0xff; }
        p3d_8(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(8-1)*8*8 + bb), m0, m1);
      } else {
        int nrow = 8 - bb; if (nrow > 8) nrow = 8;
        p3c_8(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(8-1)*8*8 + (long)bb*8), nrow);
      }
    }
  }
#endif
}
// t==1 fused: p2 + p3f (state write + emitted out1), c packed
static void pass23f_8(double*restrict are, double*restrict aim,
                        const double*restrict cpk, double*restrict eo1) {
  for (int x = 0; x < 8; x++) {
    double* ar = are + (long)x * 72; double* ai = aim + (long)x * 72;
    for (int bb = 0; bb < 8; bb += 8)
      p2_8(ar + bb, ai + bb, Sr_8 + (long)bb * 8, Si_8 + (long)bb * 8);
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      p3f_8(Sr_8 + bb, Si_8 + bb, ar + bb, ai + bb, cpk + ((long)x*1 + k)*128, eo1, x, bb);
    }
  }
}
// final step: p2 into scratch, then emit directly (no state write). parity: 1 = transposed layout (odd t), 0 = natural
static void pass23e_8(double*restrict are, double*restrict aim,
                        const double*restrict csrc, double*restrict eo1, double*restrict eo2, int parity) {
  for (int x = 0; x < 8; x++) {
    double* ar = are + (long)x * 72; double* ai = aim + (long)x * 72;
    for (int bb = 0; bb < 8; bb += 8)
      p2_8(ar + bb, ai + bb, Sr_8 + (long)bb * 8, Si_8 + (long)bb * 8);
    for (int k = 0; k < 1; k++) {
      int bb = 8 * k;
      if (parity) {
        int nrow = 8 - bb; if (nrow > 8) nrow = 8;
        p3eT_8(Sr_8 + bb, Si_8 + bb, csrc + 2*((long)x*8*8 + (long)bb*8), nrow, eo1, eo2, x, bb);
      } else {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 8) { m0 = 0xff; m1 = 0xff; }
        p3eN_8(Sr_8 + bb, Si_8 + bb, csrc + 2*((long)x*8*8 + bb), m0, m1, eo1, x, bb);
      }
    }
  }
}


static void run_8(long B, long m, const double* x0, const double* c, double* out1, double* outm) {
  long b0 = 0;

  for (long b = b0; b < B; b++) {
    const double* xb = x0 + 2 * (long)b * 512;
    const double* cb = c + 2 * (long)b * 512;
    double* o1 = out1 + 2 * (long)b * 512;
    double* om = outm + 2 * (long)b * 512;
    int useT = (m >= 3);
    int useN = (m >= 4);
    if (useT && useN) cprepBoth(cb, cPo_8, cPe_8, 8, 1, 8);
    else if (useT) cprepTpk(cb, cPo_8, 8, 1, 8);
    deintl(xb, Ar_8, Ai_8, 8, 8, 72);
    for (long t = 1; t <= m; t++) {
      pass1_8(Ar_8, Ai_8);
      if (t == m) {
        if (t & 1) pass23e_8(Ar_8, Ai_8, cb, (m == 1 ? o1 : om), (m == 1 ? om : 0), 1);
        else       pass23e_8(Ar_8, Ai_8, cb, om, 0, 0);
        break;
      }
      if (t == 1) {
        if (useT) { pass23f_8(Ar_8, Ai_8, cPo_8, o1); continue; }
        pass23_8(Ar_8, Ai_8, 0, cb, 2);
        emitT(Ar_8, Ai_8, o1, 0, 8, 8, 72, 0);
      } else if (t & 1) {
        pass23_8(Ar_8, Ai_8, cPo_8, 0, 0);
      } else {
        if (useN) pass23_8(Ar_8, Ai_8, cPe_8, 0, 0);
        else      pass23_8(Ar_8, Ai_8, 0, cb, 1);
      }
    }
  }
  _mm_sfence();
}

