static void pass1_13(double*restrict re, double*restrict im) {
#if P1ORD
  for (int bb = 0; bb < 16; bb += 8)
    for (int a = 0; a < 13; a++)
      p1_13(re + a * 16 + bb, im + a * 16 + bb);
#else
  for (int a = 0; a < 13; a++) {
    double* r = re + a * 16;
    double* i2 = im + a * 16;
    for (int bb = 0; bb < 16; bb += 8) p1_13(r + bb, i2 + bb);
  }
#endif
}
// kind: 0 -> p3 with split c planes; 1 -> p3d natural interleaved c; 2 -> p3c transposed interleaved c
static void pass23_13(double*restrict are, double*restrict aim,
                       const double*restrict cpk,
                       const double*restrict csrc, int kind) {
  double* s0r = Sr_13; double* s0i = Si_13;
  double* s1r = Sr2_13; double* s1i = Si2_13;
  for (int x = 0; x < 13; x++) {
    double* ar = are + (long)x * 264; double* ai = aim + (long)x * 264;
    double* pr = are + (long)(x-1) * 264; double* pi = aim + (long)(x-1) * 264;
    for (int k = 0; k < 2; k++) {
      int bb = 8 * k;
      p2_13(ar + bb, ai + bb, s0r + (long)bb * 16, s0i + (long)bb * 16);
    }
#if PIPE==0
    if (1) {
      double* t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
      double* pr = ar; double* pi = ai;
      int x_ = x + 1;
      (void)x_;
      for (int k = 0; k < 2; k++) {
        int bb = 8 * k;
        if (kind == 0)
          p3_13(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)x*2 + k)*256);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 13) { m0 = 0xff; m1 = 0x03; }
          p3d_13(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*13*13 + bb), m0, m1);
        } else {
          int nrow = 13 - bb; if (nrow > 8) nrow = 8;
          p3c_13(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*13*13 + (long)bb*13), nrow);
        }
      }
      // swap back so outer swap restores
      t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
    }
#else
    for (int k = 0; k < 2; k++) {
      int bb = 8 * k;
      if (x > 0) {
        if (kind == 0)
          p3_13(s1r + bb, s1i + bb, pr + bb, pi + bb, cre + (long)(x-1)*264 + bb, cim + (long)(x-1)*264 + bb);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 13) { m0 = 0xff; m1 = 0x03; }
          p3d_13(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*13*13 + bb), m0, m1);
        } else {
          int nrow = 13 - bb; if (nrow > 8) nrow = 8;
          p3c_13(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*13*13 + (long)bb*13), nrow);
        }
      }
    }
#endif
    double* t;
    t = s0r; s0r = s1r; s1r = t;
    t = s0i; s0i = s1i; s1i = t;
  }
#if PIPE==1
  {
    double* pr = are + (long)(13-1) * 264; double* pi = aim + (long)(13-1) * 264;
    for (int k = 0; k < 2; k++) {
      int bb = 8 * k;
      if (kind == 0)
        p3_13(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)(13-1)*2 + k)*256);
      else if (kind == 1) {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 13) { m0 = 0xff; m1 = 0x03; }
        p3d_13(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(13-1)*13*13 + bb), m0, m1);
      } else {
        int nrow = 13 - bb; if (nrow > 8) nrow = 8;
        p3c_13(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(13-1)*13*13 + (long)bb*13), nrow);
      }
    }
  }
#endif
}
// t==1 fused: p2 + p3f (state write + emitted out1), c packed
static void pass23f_13(double*restrict are, double*restrict aim,
                        const double*restrict cpk, double*restrict eo1) {
  for (int x = 0; x < 13; x++) {
    double* ar = are + (long)x * 264; double* ai = aim + (long)x * 264;
    for (int bb = 0; bb < 16; bb += 8)
      p2_13(ar + bb, ai + bb, Sr_13 + (long)bb * 16, Si_13 + (long)bb * 16);
    for (int k = 0; k < 2; k++) {
      int bb = 8 * k;
      p3f_13(Sr_13 + bb, Si_13 + bb, ar + bb, ai + bb, cpk + ((long)x*2 + k)*256, eo1, x, bb);
    }
  }
}
// final step: p2 into scratch, then emit directly (no state write). parity: 1 = transposed layout (odd t), 0 = natural
static void pass23e_13(double*restrict are, double*restrict aim,
                        const double*restrict csrc, double*restrict eo1, double*restrict eo2, int parity) {
  for (int x = 0; x < 13; x++) {
    double* ar = are + (long)x * 264; double* ai = aim + (long)x * 264;
    for (int bb = 0; bb < 16; bb += 8)
      p2_13(ar + bb, ai + bb, Sr_13 + (long)bb * 16, Si_13 + (long)bb * 16);
    for (int k = 0; k < 2; k++) {
      int bb = 8 * k;
      if (parity) {
        int nrow = 13 - bb; if (nrow > 8) nrow = 8;
        p3eT_13(Sr_13 + bb, Si_13 + bb, csrc + 2*((long)x*13*13 + (long)bb*13), nrow, eo1, eo2, x, bb);
      } else {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 13) { m0 = 0xff; m1 = 0x03; }
        p3eN_13(Sr_13 + bb, Si_13 + bb, csrc + 2*((long)x*13*13 + bb), m0, m1, eo1, x, bb);
      }
    }
  }
}


static void run_13(long B, long m, const double* x0, const double* c, double* out1, double* outm) {
  long b0 = 0;

  for (long b = b0; b < B; b++) {
    const double* xb = x0 + 2 * (long)b * 2197;
    const double* cb = c + 2 * (long)b * 2197;
    double* o1 = out1 + 2 * (long)b * 2197;
    double* om = outm + 2 * (long)b * 2197;
    int useT = (m >= 3);
    int useN = (m >= 4);
    if (useT && useN) cprepBoth(cb, cPo_13, cPe_13, 13, 2, 16);
    else if (useT) cprepTpk(cb, cPo_13, 13, 2, 16);
    deintl(xb, Ar_13, Ai_13, 13, 16, 264);
    for (long t = 1; t <= m; t++) {
      pass1_13(Ar_13, Ai_13);
      if (t == m) {
        if (t & 1) pass23e_13(Ar_13, Ai_13, cb, (m == 1 ? o1 : om), (m == 1 ? om : 0), 1);
        else       pass23e_13(Ar_13, Ai_13, cb, om, 0, 0);
        break;
      }
      if (t == 1) {
        if (useT) { pass23f_13(Ar_13, Ai_13, cPo_13, o1); continue; }
        pass23_13(Ar_13, Ai_13, 0, cb, 2);
        emitT(Ar_13, Ai_13, o1, 0, 13, 16, 264, 0);
      } else if (t & 1) {
        pass23_13(Ar_13, Ai_13, cPo_13, 0, 0);
      } else {
        if (useN) pass23_13(Ar_13, Ai_13, cPe_13, 0, 0);
        else      pass23_13(Ar_13, Ai_13, 0, cb, 1);
      }
    }
  }
  _mm_sfence();
}

