static void pass1_23(double*restrict re, double*restrict im) {
#if P1ORD
  for (int bb = 0; bb < 24; bb += 8)
    for (int a = 0; a < 23; a++)
      p1_23(re + a * 24 + bb, im + a * 24 + bb);
#else
  for (int a = 0; a < 23; a++) {
    double* r = re + a * 24;
    double* i2 = im + a * 24;
    for (int bb = 0; bb < 24; bb += 8) p1_23(r + bb, i2 + bb);
  }
#endif
}
// kind: 0 -> p3 with split c planes; 1 -> p3d natural interleaved c; 2 -> p3c transposed interleaved c
static void pass23_23(double*restrict are, double*restrict aim,
                       const double*restrict cpk,
                       const double*restrict csrc, int kind) {
  double* s0r = Sr_23; double* s0i = Si_23;
  double* s1r = Sr2_23; double* s1i = Si2_23;
  for (int x = 0; x < 23; x++) {
    double* ar = are + (long)x * 584; double* ai = aim + (long)x * 584;
    double* pr = are + (long)(x-1) * 584; double* pi = aim + (long)(x-1) * 584;
    for (int k = 0; k < 3; k++) {
      int bb = 8 * k;
      p2_23(ar + bb, ai + bb, s0r + (long)bb * 24, s0i + (long)bb * 24);
    }
#if PIPE==0
    if (1) {
      double* t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
      double* pr = ar; double* pi = ai;
      int x_ = x + 1;
      (void)x_;
      for (int k = 0; k < 3; k++) {
        int bb = 8 * k;
        if (kind == 0)
          p3_23(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)x*3 + k)*384);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 23) { m0 = 0xff; m1 = 0x3f; }
          p3d_23(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*23*23 + bb), m0, m1);
        } else {
          int nrow = 23 - bb; if (nrow > 8) nrow = 8;
          p3c_23(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*23*23 + (long)bb*23), nrow);
        }
      }
      // swap back so outer swap restores
      t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
    }
#else
    for (int k = 0; k < 3; k++) {
      int bb = 8 * k;
      if (x > 0) {
        if (kind == 0)
          p3_23(s1r + bb, s1i + bb, pr + bb, pi + bb, cre + (long)(x-1)*584 + bb, cim + (long)(x-1)*584 + bb);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 23) { m0 = 0xff; m1 = 0x3f; }
          p3d_23(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*23*23 + bb), m0, m1);
        } else {
          int nrow = 23 - bb; if (nrow > 8) nrow = 8;
          p3c_23(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*23*23 + (long)bb*23), nrow);
        }
      }
    }
#endif
    double* t;
    t = s0r; s0r = s1r; s1r = t;
    t = s0i; s0i = s1i; s1i = t;
  }
#if PIPE==1
  {
    double* pr = are + (long)(23-1) * 584; double* pi = aim + (long)(23-1) * 584;
    for (int k = 0; k < 3; k++) {
      int bb = 8 * k;
      if (kind == 0)
        p3_23(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)(23-1)*3 + k)*384);
      else if (kind == 1) {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 23) { m0 = 0xff; m1 = 0x3f; }
        p3d_23(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(23-1)*23*23 + bb), m0, m1);
      } else {
        int nrow = 23 - bb; if (nrow > 8) nrow = 8;
        p3c_23(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(23-1)*23*23 + (long)bb*23), nrow);
      }
    }
  }
#endif
}
// t==1 fused: p2 + p3f (state write + emitted out1), c packed
static void pass23f_23(double*restrict are, double*restrict aim,
                        const double*restrict cpk, double*restrict eo1) {
  for (int x = 0; x < 23; x++) {
    double* ar = are + (long)x * 584; double* ai = aim + (long)x * 584;
    for (int bb = 0; bb < 24; bb += 8)
      p2_23(ar + bb, ai + bb, Sr_23 + (long)bb * 24, Si_23 + (long)bb * 24);
    for (int k = 0; k < 3; k++) {
      int bb = 8 * k;
      p3f_23(Sr_23 + bb, Si_23 + bb, ar + bb, ai + bb, cpk + ((long)x*3 + k)*384, eo1, x, bb);
    }
  }
}
// final step: p2 into scratch, then emit directly (no state write). parity: 1 = transposed layout (odd t), 0 = natural
static void pass23e_23(double*restrict are, double*restrict aim,
                        const double*restrict csrc, double*restrict eo1, double*restrict eo2, int parity) {
  for (int x = 0; x < 23; x++) {
    double* ar = are + (long)x * 584; double* ai = aim + (long)x * 584;
    for (int bb = 0; bb < 24; bb += 8)
      p2_23(ar + bb, ai + bb, Sr_23 + (long)bb * 24, Si_23 + (long)bb * 24);
    for (int k = 0; k < 3; k++) {
      int bb = 8 * k;
      if (parity) {
        int nrow = 23 - bb; if (nrow > 8) nrow = 8;
        p3eT_23(Sr_23 + bb, Si_23 + bb, csrc + 2*((long)x*23*23 + (long)bb*23), nrow, eo1, eo2, x, bb);
      } else {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 23) { m0 = 0xff; m1 = 0x3f; }
        p3eN_23(Sr_23 + bb, Si_23 + bb, csrc + 2*((long)x*23*23 + bb), m0, m1, eo1, x, bb);
      }
    }
  }
}


static void run_23(long B, long m, const double* x0, const double* c, double* out1, double* outm) {
  long b0 = 0;

  for (long b = b0; b < B; b++) {
    const double* xb = x0 + 2 * (long)b * 12167;
    const double* cb = c + 2 * (long)b * 12167;
    double* o1 = out1 + 2 * (long)b * 12167;
    double* om = outm + 2 * (long)b * 12167;
    int useT = (m >= 3);
    int useN = (m >= 4);
    if (useT && useN) cprepBoth(cb, cPo_23, cPe_23, 23, 3, 24);
    else if (useT) cprepTpk(cb, cPo_23, 23, 3, 24);
    deintl(xb, Ar_23, Ai_23, 23, 24, 584);
    for (long t = 1; t <= m; t++) {
      pass1_23(Ar_23, Ai_23);
      if (t == m) {
        if (t & 1) pass23e_23(Ar_23, Ai_23, cb, (m == 1 ? o1 : om), (m == 1 ? om : 0), 1);
        else       pass23e_23(Ar_23, Ai_23, cb, om, 0, 0);
        break;
      }
      if (t == 1) {
        if (useT) { pass23f_23(Ar_23, Ai_23, cPo_23, o1); continue; }
        pass23_23(Ar_23, Ai_23, 0, cb, 2);
        emitT(Ar_23, Ai_23, o1, 0, 23, 24, 584, 0);
      } else if (t & 1) {
        pass23_23(Ar_23, Ai_23, cPo_23, 0, 0);
      } else {
        if (useN) pass23_23(Ar_23, Ai_23, cPe_23, 0, 0);
        else      pass23_23(Ar_23, Ai_23, 0, cb, 1);
      }
    }
  }
  _mm_sfence();
}

