static void pass1_36(double*restrict re, double*restrict im) {
#if P1ORD
  for (int bb = 0; bb < 40; bb += 8)
    for (int a = 0; a < 36; a++)
      p1_36(re + a * 40 + bb, im + a * 40 + bb);
#else
  for (int a = 0; a < 36; a++) {
    double* r = re + a * 40;
    double* i2 = im + a * 40;
    for (int bb = 0; bb < 40; bb += 8) p1_36(r + bb, i2 + bb);
  }
#endif
}
// kind: 0 -> p3 with split c planes; 1 -> p3d natural interleaved c; 2 -> p3c transposed interleaved c
static void pass23_36(double*restrict are, double*restrict aim,
                       const double*restrict cpk,
                       const double*restrict csrc, int kind) {
  double* s0r = Sr_36; double* s0i = Si_36;
  double* s1r = Sr2_36; double* s1i = Si2_36;
  for (int x = 0; x < 36; x++) {
    double* ar = are + (long)x * 1608; double* ai = aim + (long)x * 1608;
    double* pr = are + (long)(x-1) * 1608; double* pi = aim + (long)(x-1) * 1608;
    for (int k = 0; k < 5; k++) {
      int bb = 8 * k;
      p2_36(ar + bb, ai + bb, s0r + (long)bb * 40, s0i + (long)bb * 40);
    }
#if PIPE==0
    if (1) {
      double* t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
      double* pr = ar; double* pi = ai;
      int x_ = x + 1;
      (void)x_;
      for (int k = 0; k < 5; k++) {
        int bb = 8 * k;
        if (kind == 0)
          p3_36(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)x*5 + k)*640);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 36) { m0 = 0xff; m1 = 0x00; }
          p3d_36(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*36*36 + bb), m0, m1);
        } else {
          int nrow = 36 - bb; if (nrow > 8) nrow = 8;
          p3c_36(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*36*36 + (long)bb*36), nrow);
        }
      }
      // swap back so outer swap restores
      t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
    }
#else
    for (int k = 0; k < 5; k++) {
      int bb = 8 * k;
      if (x > 0) {
        if (kind == 0)
          p3_36(s1r + bb, s1i + bb, pr + bb, pi + bb, cre + (long)(x-1)*1608 + bb, cim + (long)(x-1)*1608 + bb);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 36) { m0 = 0xff; m1 = 0x00; }
          p3d_36(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*36*36 + bb), m0, m1);
        } else {
          int nrow = 36 - bb; if (nrow > 8) nrow = 8;
          p3c_36(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*36*36 + (long)bb*36), nrow);
        }
      }
    }
#endif
    double* t;
    t = s0r; s0r = s1r; s1r = t;
    t = s0i; s0i = s1i; s1i = t;
  }
#if PIPE==1
  {
    double* pr = are + (long)(36-1) * 1608; double* pi = aim + (long)(36-1) * 1608;
    for (int k = 0; k < 5; k++) {
      int bb = 8 * k;
      if (kind == 0)
        p3_36(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)(36-1)*5 + k)*640);
      else if (kind == 1) {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 36) { m0 = 0xff; m1 = 0x00; }
        p3d_36(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(36-1)*36*36 + bb), m0, m1);
      } else {
        int nrow = 36 - bb; if (nrow > 8) nrow = 8;
        p3c_36(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(36-1)*36*36 + (long)bb*36), nrow);
      }
    }
  }
#endif
}
// t==1 fused: p2 + p3f (state write + emitted out1), c packed
static void pass23f_36(double*restrict are, double*restrict aim,
                        const double*restrict cpk, double*restrict eo1) {
  for (int x = 0; x < 36; x++) {
    double* ar = are + (long)x * 1608; double* ai = aim + (long)x * 1608;
    for (int bb = 0; bb < 40; bb += 8)
      p2_36(ar + bb, ai + bb, Sr_36 + (long)bb * 40, Si_36 + (long)bb * 40);
    for (int k = 0; k < 5; k++) {
      int bb = 8 * k;
      p3f_36(Sr_36 + bb, Si_36 + bb, ar + bb, ai + bb, cpk + ((long)x*5 + k)*640, eo1, x, bb);
    }
  }
}
// final step: p2 into scratch, then emit directly (no state write). parity: 1 = transposed layout (odd t), 0 = natural
static void pass23e_36(double*restrict are, double*restrict aim,
                        const double*restrict csrc, double*restrict eo1, double*restrict eo2, int parity) {
  for (int x = 0; x < 36; x++) {
    double* ar = are + (long)x * 1608; double* ai = aim + (long)x * 1608;
    for (int bb = 0; bb < 40; bb += 8)
      p2_36(ar + bb, ai + bb, Sr_36 + (long)bb * 40, Si_36 + (long)bb * 40);
    for (int k = 0; k < 5; k++) {
      int bb = 8 * k;
      if (parity) {
        int nrow = 36 - bb; if (nrow > 8) nrow = 8;
        p3eT_36(Sr_36 + bb, Si_36 + bb, csrc + 2*((long)x*36*36 + (long)bb*36), nrow, eo1, eo2, x, bb);
      } else {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 36) { m0 = 0xff; m1 = 0x00; }
        p3eN_36(Sr_36 + bb, Si_36 + bb, csrc + 2*((long)x*36*36 + bb), m0, m1, eo1, x, bb);
      }
    }
  }
}


static void run_36(long B, long m, const double* x0, const double* c, double* out1, double* outm) {
  long b0 = 0;

  for (long b = b0; b < B; b++) {
    const double* xb = x0 + 2 * (long)b * 46656;
    const double* cb = c + 2 * (long)b * 46656;
    double* o1 = out1 + 2 * (long)b * 46656;
    double* om = outm + 2 * (long)b * 46656;
    int useT = (m >= 3);
    int useN = (m >= 4);
    if (useT && useN) cprepBoth(cb, cPo_36, cPe_36, 36, 5, 40);
    else if (useT) cprepTpk(cb, cPo_36, 36, 5, 40);
    deintl(xb, Ar_36, Ai_36, 36, 40, 1608);
    for (long t = 1; t <= m; t++) {
      pass1_36(Ar_36, Ai_36);
      if (t == m) {
        if (t & 1) pass23e_36(Ar_36, Ai_36, cb, (m == 1 ? o1 : om), (m == 1 ? om : 0), 1);
        else       pass23e_36(Ar_36, Ai_36, cb, om, 0, 0);
        break;
      }
      if (t == 1) {
        if (useT) { pass23f_36(Ar_36, Ai_36, cPo_36, o1); continue; }
        pass23_36(Ar_36, Ai_36, 0, cb, 2);
        emitT(Ar_36, Ai_36, o1, 0, 36, 40, 1608, 1);
      } else if (t & 1) {
        pass23_36(Ar_36, Ai_36, cPo_36, 0, 0);
      } else {
        if (useN) pass23_36(Ar_36, Ai_36, cPe_36, 0, 0);
        else      pass23_36(Ar_36, Ai_36, 0, cb, 1);
      }
    }
  }
  _mm_sfence();
}

