static void pass1_64(double*restrict re, double*restrict im) {
#if P1ORD
  for (int bb = 0; bb < 64; bb += 8)
    for (int a = 0; a < 64; a++)
      p1_64(re + a * 64 + bb, im + a * 64 + bb);
#else
  for (int a = 0; a < 64; a++) {
    double* r = re + a * 64;
    double* i2 = im + a * 64;
    for (int bb = 0; bb < 64; bb += 8) p1_64(r + bb, i2 + bb);
  }
#endif
}
// kind: 0 -> p3 with split c planes; 1 -> p3d natural interleaved c; 2 -> p3c transposed interleaved c
static void pass23_64(double*restrict are, double*restrict aim,
                       const double*restrict cpk,
                       const double*restrict csrc, int kind) {
  double* s0r = Sr_64; double* s0i = Si_64;
  double* s1r = Sr2_64; double* s1i = Si2_64;
  for (int x = 0; x < 64; x++) {
    double* ar = are + (long)x * 4104; double* ai = aim + (long)x * 4104;
    double* pr = are + (long)(x-1) * 4104; double* pi = aim + (long)(x-1) * 4104;
    for (int k = 0; k < 8; k++) {
      int bb = 8 * k;
      p2_64(ar + bb, ai + bb, s0r + (long)bb * 64, s0i + (long)bb * 64);
    }
#if PIPE==0
    if (1) {
      double* t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
      double* pr = ar; double* pi = ai;
      int x_ = x + 1;
      (void)x_;
      for (int k = 0; k < 8; k++) {
        int bb = 8 * k;
        if (kind == 0)
          p3_64(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)x*8 + k)*1024);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 64) { m0 = 0xff; m1 = 0xff; }
          p3d_64(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*64*64 + bb), m0, m1);
        } else {
          int nrow = 64 - bb; if (nrow > 8) nrow = 8;
          p3c_64(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)x*64*64 + (long)bb*64), nrow);
        }
      }
      // swap back so outer swap restores
      t = s0r; s0r = s1r; s1r = t;
      t = s0i; s0i = s1i; s1i = t;
    }
#else
    for (int k = 0; k < 8; k++) {
      int bb = 8 * k;
      if (x > 0) {
        if (kind == 0)
          p3_64(s1r + bb, s1i + bb, pr + bb, pi + bb, cre + (long)(x-1)*4104 + bb, cim + (long)(x-1)*4104 + bb);
        else if (kind == 1) {
          __mmask8 m0 = 0xFF, m1 = 0xFF;
          if (bb + 8 > 64) { m0 = 0xff; m1 = 0xff; }
          p3d_64(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*64*64 + bb), m0, m1);
        } else {
          int nrow = 64 - bb; if (nrow > 8) nrow = 8;
          p3c_64(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(x-1)*64*64 + (long)bb*64), nrow);
        }
      }
    }
#endif
    double* t;
    t = s0r; s0r = s1r; s1r = t;
    t = s0i; s0i = s1i; s1i = t;
  }
#if PIPE==1
  {
    double* pr = are + (long)(64-1) * 4104; double* pi = aim + (long)(64-1) * 4104;
    for (int k = 0; k < 8; k++) {
      int bb = 8 * k;
      if (kind == 0)
        p3_64(s1r + bb, s1i + bb, pr + bb, pi + bb, cpk + ((long)(64-1)*8 + k)*1024);
      else if (kind == 1) {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 64) { m0 = 0xff; m1 = 0xff; }
        p3d_64(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(64-1)*64*64 + bb), m0, m1);
      } else {
        int nrow = 64 - bb; if (nrow > 8) nrow = 8;
        p3c_64(s1r + bb, s1i + bb, pr + bb, pi + bb, csrc + 2*((long)(64-1)*64*64 + (long)bb*64), nrow);
      }
    }
  }
#endif
}
// t==1 fused: p2 + p3f (state write + emitted out1), c packed
static void pass23f_64(double*restrict are, double*restrict aim,
                        const double*restrict cpk, double*restrict eo1) {
  for (int x = 0; x < 64; x++) {
    double* ar = are + (long)x * 4104; double* ai = aim + (long)x * 4104;
    for (int bb = 0; bb < 64; bb += 8)
      p2_64(ar + bb, ai + bb, Sr_64 + (long)bb * 64, Si_64 + (long)bb * 64);
    for (int k = 0; k < 8; k++) {
      int bb = 8 * k;
      p3f_64(Sr_64 + bb, Si_64 + bb, ar + bb, ai + bb, cpk + ((long)x*8 + k)*1024, eo1, x, bb);
    }
  }
}
// final step: p2 into scratch, then emit directly (no state write). parity: 1 = transposed layout (odd t), 0 = natural
static void pass23e_64(double*restrict are, double*restrict aim,
                        const double*restrict csrc, double*restrict eo1, double*restrict eo2, int parity) {
  for (int x = 0; x < 64; x++) {
    double* ar = are + (long)x * 4104; double* ai = aim + (long)x * 4104;
    for (int bb = 0; bb < 64; bb += 8)
      p2_64(ar + bb, ai + bb, Sr_64 + (long)bb * 64, Si_64 + (long)bb * 64);
    for (int k = 0; k < 8; k++) {
      int bb = 8 * k;
      if (parity) {
        int nrow = 64 - bb; if (nrow > 8) nrow = 8;
        p3eT_64(Sr_64 + bb, Si_64 + bb, csrc + 2*((long)x*64*64 + (long)bb*64), nrow, eo1, eo2, x, bb);
      } else {
        __mmask8 m0 = 0xFF, m1 = 0xFF;
        if (bb + 8 > 64) { m0 = 0xff; m1 = 0xff; }
        p3eN_64(Sr_64 + bb, Si_64 + bb, csrc + 2*((long)x*64*64 + bb), m0, m1, eo1, x, bb);
      }
    }
  }
}


static void run_64(long B, long m, const double* x0, const double* c, double* out1, double* outm) {
  long b0 = 0;

  for (long b = b0; b < B; b++) {
    const double* xb = x0 + 2 * (long)b * 262144;
    const double* cb = c + 2 * (long)b * 262144;
    double* o1 = out1 + 2 * (long)b * 262144;
    double* om = outm + 2 * (long)b * 262144;
    int useT = (m >= 3);
    int useN = (m >= 4);
    if (useT && useN) cprepBoth(cb, cPo_64, cPe_64, 64, 8, 64);
    else if (useT) cprepTpk(cb, cPo_64, 64, 8, 64);
    deintl(xb, Ar_64, Ai_64, 64, 64, 4104);
    for (long t = 1; t <= m; t++) {
      pass1_64(Ar_64, Ai_64);
      if (t == m) {
        if (t & 1) pass23e_64(Ar_64, Ai_64, cb, (m == 1 ? o1 : om), (m == 1 ? om : 0), 1);
        else       pass23e_64(Ar_64, Ai_64, cb, om, 0, 0);
        break;
      }
      if (t == 1) {
        if (useT) { pass23f_64(Ar_64, Ai_64, cPo_64, o1); continue; }
        pass23_64(Ar_64, Ai_64, 0, cb, 2);
        emitT(Ar_64, Ai_64, o1, 0, 64, 64, 4104, 1);
      } else if (t & 1) {
        pass23_64(Ar_64, Ai_64, cPo_64, 0, 0);
      } else {
        if (useN) pass23_64(Ar_64, Ai_64, cPe_64, 0, 0);
        else      pass23_64(Ar_64, Ai_64, 0, cb, 1);
      }
    }
  }
  _mm_sfence();
}


static double* alloc0(long n) {
  long bytes = ((n * 8 + 2097151) / 2097152) * 2097152;
  double* p = (double*)aligned_alloc(2097152, bytes);
  if (p) madvise(p, bytes, MADV_HUGEPAGE);
  if (!p) p = (double*)aligned_alloc(64, bytes);
  if (!p) { p = (double*)malloc(bytes + 64); p = (double*)(((uintptr_t)p + 63) & ~(uintptr_t)63); }
  memset(p, 0, bytes);
  return p;
}
